// Prepare a stringstream* with a synthetic command line and attempt replacements.
std::stringstream local_ss;
local_ss << "--learning_rate 0.5 --loss_function squared --passes 1";
std::stringstream* ss_ptr = &local_ss;

// Replace a flag value; try a few common flags to exercise code paths.
VW::cmd_string_replace_value(ss_ptr, "--learning_rate", "0.1");
VW::cmd_string_replace_value(ss_ptr, "--passes", "2");
// No validation guarantees; this function is deprecated and void-return.

// Convert a fuzzed command line into argv and immediately free it to respect API contract.
try {
  std::string cmd = FUZZ_PARAM_STR();
  int argc = 0;
  char** argv = VW::to_argv(cmd, argc);
  // Must free via VW::free_args(argc, argv)
  if (argv != nullptr) { VW::free_args(argc, argv); }
}
catch (const std::exception&) { FUZZ_BAIL(); }

// Convert an escaped command line into argv and free it.
try {
  std::string cmd = FUZZ_PARAM_STR();
