  if (argv != nullptr) { VW::free_args(argc, argv); }
}
catch (const std::exception&) { FUZZ_BAIL(); }

// This function requires argv returned from VW::to_argv or VW::to_argv_escaped.
// Create such argv here, then free it to exercise the API.
try {
  std::string cmd = FUZZ_PARAM_STR();
  int argc = 0;
  char** argv = VW::to_argv(cmd, argc);
  if (argv == nullptr) { FUZZ_BAIL(); }
  VW::free_args(argc, argv);
}
catch (const std::exception&) { FUZZ_BAIL(); }

// Create two independent workspaces, then query compatibility. Clean up both.
try {
  std::string args1 = FUZZ_PARAM_STR();
  std::string args2 = FUZZ_PARAM_STR();
  VW::workspace* a = VW::initialize(args1, nullptr, false, nullptr, nullptr);
  VW::workspace* b = VW::initialize(args2, nullptr, false, nullptr, nullptr);
  if (a == nullptr || b == nullptr) { FUZZ_BAIL(); }

  (void)VW::are_features_compatible(*a, *b);

  // Finish and delete both to avoid leaks.
  VW::finish(*a, /*delete_all*/ true);
  VW::finish(*b, /*delete_all*/ true);
}
catch (const std::exception&) { FUZZ_BAIL(); }

// Validate workspace handle and finalize it. This should be called exactly once per instance.
const char* t = FUZZ_GET_ATTR_STR(vw, "type");
int alive = FUZZ_GET_ATTR_INT(vw, "alive");
if (!(t && !strcmp(t, "vw_workspace") && alive == 1)) { FUZZ_BAIL(); }

try {
  VW::workspace* raw = static_cast<VW::workspace*>(vw);
  // For workspaces created by string/escaped initialize in this harness, delete_all=true is correct.
  VW::finish(*raw, /*delete_all*/ true);
  FUZZ_SET_ATTR_INT(vw, "alive", 0);
}
catch (const std::exception&) { FUZZ_BAIL(); }

// Synchronize statistics for a valid workspace.
const char* t = FUZZ_GET_ATTR_STR(vw, "type");
int alive = FUZZ_GET_ATTR_INT(vw, "alive");
if (!(t && !strcmp(t, "vw_workspace") && alive == 1)) { FUZZ_BAIL(); }
try {
