// Create a small batch (multi_ex), call setup_examples, then finish them.
const char* t = FUZZ_GET_ATTR_STR(vw, "type");
int alive = FUZZ_GET_ATTR_INT(vw, "alive");
if (!(t && !strcmp(t, "vw_workspace") && alive == 1)) { FUZZ_BAIL(); }
try {
  VW::workspace* raw = static_cast<VW::workspace*>(vw);
  std::string line1 = "1 |ns f:1";
  std::string line2 = "-1 |ns g:2";
  VW::example* e1 = VW::read_example(*raw, line1);
  VW::example* e2 = VW::read_example(*raw, line2);
  if (e1 == nullptr || e2 == nullptr) { FUZZ_BAIL(); }
  VW::multi_ex mex;
  mex.push_back(e1);
  mex.push_back(e2);
  VW::setup_examples(*raw, mex);
  // Finish lifecycle
  VW::finish_example(*raw, mex);
}
catch (const std::exception&) { FUZZ_BAIL(); }

// Create a single example, set it up, then finish it to respect lifecycle.
const char* t = FUZZ_GET_ATTR_STR(vw, "type");
