// Create a temporary workspace configured for a topic model (LDA) and query index 0.
try {
  VW::workspace* vw = VW::initialize("--quiet --lda 2 --random_seed 5", nullptr, false, nullptr, nullptr);
  if (!vw) { FUZZ_BAIL(); }
  // Build a simple example; LDA ignores labels, but include features.
  VW::example* ec = VW::read_example(*vw, "|t f:1.0 g:0.5");
  if (!ec) { VW::finish(*vw, true); FUZZ_BAIL(); }
  // Query topic prediction at i=0 (valid as lda=2 ensures at least 2 topics).
  (void)VW::get_topic_prediction(ec, 0);
  VW::finish_example(*vw, *ec);
  VW::finish(*vw, true);
}
catch (const std::exception&) { FUZZ_BAIL(); }

