// Safely compute an index using the action score length, then query that index if available.
try {
  VW::workspace* vw = VW::initialize("--quiet --cb 2 --random_seed 14", nullptr, false, nullptr, nullptr);
  if (!vw) { FUZZ_BAIL(); }
  // Use a contextual bandit style example to increase chances of action scores being present.
  VW::example* ec = VW::read_example(*vw, "shared |s f:1\n0:1:0.1 |a f:0.2\n0:0:0.1 |b g:0.3\n");
  if (!ec) { VW::finish(*vw, true); FUZZ_BAIL(); }
  size_t n = VW::get_action_score_length(ec);
  size_t i = (n > 0) ? (0 % n) : 0;
  (void)VW::get_action_score(ec, i);
  VW::finish_example(*vw, *ec);
  VW::finish(*vw, true);
}
catch (const std::exception&) { FUZZ_BAIL(); }

