import random
import string
from typing import List

# Generator for escaped command-line arguments expected by VW::to_argv_escaped
# Requirements:
# - Produce a single command line string where tokens are separated by spaces
# - Spaces inside tokens must be escaped with backslashes
# - Support quotes and mixed escaping as VW historically accepts backslash-escaped spaces
# - Return as bytes (UTF-8) and <= 4096 bytes

_ESCAPABLE = {
    ' ': '\\ ',
    '\t': '\\t',
    '\n': '\\n',
}

FLAG_POOL = [
    # common VW flags
    "-f", "--final_regressor", "--readable_model", "--quiet", "--binary", "--audit", "--cubic",
    "--kill_cache", "--hash", "--oaa", "--cb", "--cb_explore", "--cb_adf", "-l", "--l2",
    "--l1", "--loss_function", "--link", "-b", "--bit_precision", "--ngram", "--skips",
    "--holdout_off", "--compressed", "--random_seed", "--passes", "--cache", "--data",
    "--initial_regressor", "--inv_hash", "--names", "--keep", "--ignore", "--spelling", "--help",
]

HASHERS = ["all", "string", "murmur", "xxhash", "fnv"]
LOSSES = ["squared", "hinge", "logistic", "quantile", "poisson"]
LINKS = ["identity", "logistic"]

SAFE_FILENAME_CHARS = string.ascii_letters + string.digits + "_-./"

def _rand_ident(r: random.Random, min_len=1, max_len=8) -> str:
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(string.ascii_letters + string.digits + "_-") for _ in range(n))

def _escape_token(tok: str) -> str:
    # Escape spaces and some whitespace explicitly; also randomly inject escapes before some chars
    out = []
    for ch in tok:
        if ch in _ESCAPABLE:
            out.append(_ESCAPABLE[ch])
        elif ch == '\\':
            out.append('\\\\')
        else:
            out.append(ch)
    return ''.join(out)

def _maybe_escape_spaces(r: random.Random, s: str) -> str:
    # Convert internal spaces to escaped spaces with some probability
    if ' ' not in s:
        return s
    parts = s.split(' ')
    # Re-join using either space or escaped space depending per-gap to create mixed cases
    out = parts[0]
    for p in parts[1:]:
        out += ("\\ " if r.random() < 0.8 else " ") + p
    return out

def _val_for_flag(r: random.Random, flag: str) -> str | None:
    # Provide plausible values for known flags
    if flag in ("--hash",):
        return r.choice(HASHERS)
    if flag in ("--loss_function",):
        return r.choice(LOSSES)
    if flag in ("--link",):
        return r.choice(LINKS)
    if flag in ("-b", "--bit_precision"):
        return str(r.choice([8, 10, 12, 18, 20, 24]))
    if flag in ("-l",):
        return f"{r.uniform(1e-6, 1.0):.6f}"
    if flag in ("--l1", "--l2"):
        return f"{r.uniform(0.0, 1e-2):.8f}"
    if flag in ("--oaa", "--cb", "--passes"):
        return str(r.randint(1, 50))
    if flag in ("--random_seed",):
        return str(r.randrange(0, 2**31))
    if flag in ("--cubic",):
        # triplet of namespaces, letters a-z
        return ''.join(r.choice(string.ascii_lowercase) for _ in range(3))
    if flag in ("--ngram", "--skips"):
        # namespace and integer
        ns = r.choice(string.ascii_lowercase)
        return f"{ns}{r.randint(1, 4)}"
    if flag in ("--keep", "--ignore"):
        return r.choice(string.ascii_lowercase)
    if flag in ("--data", "--final_regressor", "--readable_model", "--initial_regressor"):
        # a plausible filename, possibly with spaces that are escaped
        base = _rand_ident(r, 3, 8)
        ext = r.choice([".vw", ".model", ".txt", ".dat", ""]) \
              if flag != "--data" else r.choice([".vw", ".txt", ""]) 
        path = r.choice(["./", "", "models/", "data/"]) + base + ext
        # maybe insert a space to exercise escaping
        if r.random() < 0.4:
            path = path + " " + _rand_ident(r, 2, 5)
        return path
    if flag in ("--names",):
        # comma separated names, possibly with spaces
        items = [r.choice(["a", "b", "c", "ns", _rand_ident(r)]) for _ in range(r.randint(1, 4))]
        s = ','.join(items)
        if r.random() < 0.5:
            s = s + " " + _rand_ident(r)
        return s
    if flag in ("--spelling",):
        return r.choice(["double", "single"])
    # flags that often are toggles
    return None

def _random_positional_example(r: random.Random) -> str:
    # Create a small VW example line; allow escaped spaces in feature names or values
    # label |ns f1:val f2
    label = r.choice(["1", "-1", "0", "2.5", "0.0"]) if r.random() < 0.7 else ""
    ns = r.choice(["|a", "|b", "|user", "| ", "|"])  # include odd namespace tokens
    feats: List[str] = []
    for _ in range(r.randint(1, 5)):
        name = _rand_ident(r, 1, 6)
        # maybe embed a space that needs escaping
        if r.random() < 0.3:
            name = name + " " + _rand_ident(r, 1, 3)
        val = (":" + f"{r.uniform(-2.0, 3.0):.6f}") if r.random() < 0.7 else ""
        tok = name + val
        tok = _maybe_escape_spaces(r, tok)
        feats.append(tok)
    parts = [p for p in [label, ns] if p]
    parts.extend(feats)
    return ' '.join(parts)

def _build_command(r: random.Random) -> str:
    tokens: List[str] = []

    # Start with program name-like token (ignored by VW::to_argv_escaped but realistic)
    prog = r.choice(["vw", "vw.exe", "my vw"])  # include space to exercise escaping
    tokens.append(_maybe_escape_spaces(r, prog))

    # Add a mix of flags with and without values
    nflags = r.randint(1, 10)
    chosen = r.sample(FLAG_POOL, k=nflags)
    for flag in chosen:
        tokens.append(flag)
        val = _val_for_flag(r, flag)
        if val is not None:
            # Escape spaces inside value
            tokens.append(_maybe_escape_spaces(r, val))

    # Sometimes repeat a flag to exercise replacement/dup behavior
    if r.random() < 0.3:
        flag = r.choice(FLAG_POOL)
        tokens.append(flag)
        val = _val_for_flag(r, flag)
        if val is not None:
            tokens.append(_maybe_escape_spaces(r, val))

    # Add one or two positional example strings as trailing args (some VW tools accept)
    if r.random() < 0.6:
        tokens.append(_random_positional_example(r))
    if r.random() < 0.3:
        tokens.append(_random_positional_example(r))

    # Randomly sprinkle standalone escaped spaces sequence to test parser robustness
    if r.random() < 0.2:
        tokens.insert(r.randrange(1, len(tokens)+1), "\\ ")

    # Escape any backslashes and tabs/newlines
    tokens = [_escape_token(t) for t in tokens]

    cmd = ' '.join(tokens)
    # Ensure byte-size limit
    if len(cmd.encode('utf-8')) > 4096:
        cmd = cmd.encode('utf-8')[:4096].decode('utf-8', errors='ignore')
    return cmd


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    cmd = _build_command(r)
    return cmd.encode('utf-8')

