# Generator for VW text example lines
# Aim: produce valid, varied single-line examples that parse under many VW configs.
# Coverage dimensions:
# - Labels: scalar, with/without weight/base, probabilistic, multiclass, multilabel
# - Namespaces: default, named, indexed char, multiple, with/without constant, with quadratic tokens
# - Features: numeric values, integer/float, negative/zero/large, repeated feature names, explicit indices
# - Tags: optional, various lengths
# - Interactions: include feature=value style and plain tokens
# - Importance (weight) and initial prediction (base)

# Constraints:
# - Return bytes <= 4096
# - Single line; no trailing NUL


def _rand(r: random.Random, a: float, b: float) -> float:
    return r.uniform(a, b)


def _choose(r: random.Random, arr):
    return arr[r.randrange(len(arr))]


def _word(r: random.Random, min_len=1, max_len=8, alphabet=None):
    if alphabet is None:
        alphabet = string.ascii_letters + string.digits + "_-."
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(alphabet) for _ in range(n))


def _feature_name(r: random.Random) -> str:
    # Include chance of feature=value tokens
    base = _word(r, 1, r.randint(3, 10))
    if r.random() < 0.3:
        val = _word(r, 1, r.randint(1, 6))
        return f"{base}={val}"
    return base


def _num_value(r: random.Random) -> float:
    # Diverse numeric spectrum
    bucket = r.random()
