    if r.random() < 0.7:
        w = max(0.0, abs(r.uniform(0.0, 5.0)))
        parts.append(f"{w:.6g}")
        if r.random() < 0.5:
            b = r.uniform(-5.0, 5.0)
            parts.append(f"{b:.6g}")
    return ' '.join(parts)


def _label_multiclass(r: random.Random) -> str:
    # multiclass: integer class id starting at 1 typically
    c = _int_value(r, 1, 10)
    if r.random() < 0.5:
        w = max(0.0, abs(r.uniform(0.1, 5.0)))
        return f"{c} {w:.6g}"
    return str(c)


def _label_multilabel(r: random.Random) -> str:
    # multilabel: space-separated integers inside labels like 1,3,5 (VW expects e.g., 1,2,3 inside label? In text usually '1,3,5')
    # VW multilabel format: space-separated integers after label type is configured; but generic parsing accepts like '1,3,5'
    # To remain broadly valid, provide scalar or multiclass mostly; multilabel as tag-like fallback
    # We'll output as comma-separated list '1,3,5'
    k = r.randint(1, 5)
    labs = sorted(set(_int_value(r, 1, 8) for _ in range(k)))
    return ','.join(str(x) for x in labs)


def _label_cost_sensitive(r: random.Random) -> str:
    # cs: a:cost a:cost ... e.g., '1:0.5 2:1.0'
    k = r.randint(1, 4)
    parts = []
    used = set()
    for _ in range(k):
        a = _int_value(r, 1, 8)
        if a in used:
            continue
        used.add(a)
        cost = max(0.0, r.uniform(0.0, 5.0))
        parts.append(f"{a}:{cost:.6g}")
    if not parts:
        parts.append("1:0")
    return ' '.join(parts)


def _maybe_tag(r: random.Random) -> str:
    if r.random() < 0.6:
        tag_len = r.randint(0, 16)
        tag = _word(r, max(1, tag_len), max(1, tag_len)) if tag_len > 0 else ''
        return f"'{tag}"  # leading single-quote denotes tag
    return ''


def _namespace_name(r: random.Random) -> str:
    # VW supports single char namespace or string name via letters before pipe; after '|' first token optional name, ':' weight
    # Following common forms: |, |ns, |A, |ns:2.0
    base = ''
    if r.random() < 0.5:
        # single char
        base = r.choice(string.ascii_letters + string.digits)
    else:
        base = _word(r, 1, r.randint(2, 8))
    if r.random() < 0.4:
        # with namespace weight
        ns_w = max(0.0, r.uniform(0.1, 5.0))
        return f"{base}:{ns_w:.6g}"
    return base


def _feature_token(r: random.Random) -> str:
    # format: name[:value] or numeric_index:value
    if r.random() < 0.2:
        # numeric index
        idx = _int_value(r, 1, 1 << r.randint(4, 12))
        val = _num_value(r)
        return f"{idx}:{val:.6g}"
    name = _feature_name(r)
    if r.random() < 0.7:
        val = _num_value(r)
        return f"{name}:{val:.6g}"
    return name


def _namespace_block(r: random.Random) -> str:
    name = _namespace_name(r)
    feat_count = r.randint(0, 12)
    feats = []
    for _ in range(feat_count):
        feats.append(_feature_token(r))
    # Encourage at least one feature sometimes
    if not feats and r.random() < 0.7:
        feats.append(_feature_token(r))
    if name:
        return '|'+name+' '+(' '.join(feats)).strip()
    else:
        return '|'+' '+(' '.join(feats)).strip()


def _make_line(r: random.Random) -> str:
    # Select label style
    label_style = _choose(r, ['scalar', 'multiclass', 'costs', 'none'])
    if label_style == 'scalar':
        label = _label_scalar(r)
    elif label_style == 'multiclass':
        label = _label_multiclass(r)
    elif label_style == 'costs':
        label = _label_cost_sensitive(r)
    else:
        label = ''

    tag = _maybe_tag(r)

    # Number of namespaces
    ns_count = r.randint(1, 4)
    namespaces = []
    for _ in range(ns_count):
        namespaces.append(_namespace_block(r))

    # Ensure there is at least one feature overall
    if all(len(ns.strip().split()) <= 1 for ns in namespaces):
        # inject a feature into first namespace
        ns0 = namespaces[0]
        if ns0.endswith('|') or ns0.strip() == '|':
            ns0 = ns0 + ' ' + _feature_token(r)
        else:
            ns0 = ns0 + ' ' + _feature_token(r)
        namespaces[0] = ns0

    pieces = []
    if label:
        pieces.append(label)
    if tag:
        pieces.append(tag)
    pieces.extend(n for n in namespaces if n.strip())

    line = ' '.join(p.strip() for p in pieces if p is not None and str(p).strip() != '')

    # Add optional extra namespaces for coverage of default namespace '|'
    if r.random() < 0.2:
        feats = ' '.join(_feature_token(r) for _ in range(r.randint(1, 4)))
        line += ' | ' + feats

    # Trim and ensure single line
    return line.strip()


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Create multiple candidate lines and pick one by additional randomness
    candidates = []
    for _ in range(r.randint(1, 4)):
        candidates.append(_make_line(r))
    line = _choose(r, candidates)
    # Ensure not exceeding size and is non-empty with at least one namespace
    if not line or '|' not in line:
        line = "0 | f:1"
    b = line.encode('utf-8')
    if len(b) > 4096:
        b = b[:4096]
    return b
